function lastValue(amounts){
  // amounts already in ORDER BY day order
  const out = [];
  for (let i = 0; i < amounts.length; i++){
    const frame = amounts.slice(0, i + 1); // UNBOUNDED PRECEDING .. CURRENT ROW
    out.push(frame[frame.length - 1]);
  }
  return out;
}

